import {
  InstrumentEffects,
  LIVE_INPUT_EFFECTS_KEY,
  normalizeEffects,
} from 'app/services/EffectsService/settings';
import { getEffectsTail } from 'app/services/MelodyExportService/audio';
import { createEffectsRack } from 'app/services/SynthesizerService/effects';

import type { GuitarTake } from './capture';
import { NoiseGateSettings, defaultNoiseGate } from './noiseGateSettings';
import { applyOfflineNoiseGate } from './offlineNoiseGate';

export const renderGuitarAudio = async (
  take: GuitarTake,
  effects: InstrumentEffects,
  noiseGate: NoiseGateSettings = defaultNoiseGate,
): Promise<AudioBuffer> => {
  if (!window.OfflineAudioContext)
    throw new Error(
      'This browser does not support recording processing. Download a clean WAV or update your browser.',
    );
  if (!take.samples.length)
    throw new Error('The audio recording is empty. Record a new take.');
  const settings = normalizeEffects(LIVE_INPUT_EFFECTS_KEY, effects);
  const audio = new OfflineAudioContext(
    2,
    take.samples.length + Math.ceil(getEffectsTail(settings) * take.sampleRate),
    take.sampleRate,
  );
  const buffer = audio.createBuffer(1, take.samples.length, take.sampleRate);
  buffer
    .getChannelData(0)
    .set(applyOfflineNoiseGate(take.samples, take.sampleRate, noiseGate));
  const source = audio.createBufferSource();
  source.buffer = buffer;
  const rack = createEffectsRack(audio, audio.destination, settings, {
    lowLatency: true,
    settingsKey: LIVE_INPUT_EFFECTS_KEY,
  });
  try {
    source.connect(rack.input);
    source.start(0);
    return await audio.startRendering();
  } finally {
    source.disconnect();
    rack.dispose();
  }
};
